def build_licensed_exam_questions():
    """Return exactly 100 idempotent seed rows for licensed physician mock exams."""
    rows = list(LICENSED_EXAM_QUESTIONS)
    source = list(LICENSED_EXAM_QUESTIONS)
    index = 0
    while len(rows) < 100:
        chapter, subject, content, options, answer, explanation, difficulty = source[index % len(source)]
        variant = (index // len(source)) + 2
        rows.append(
            (
                chapter,
                subject,
                f"{content}（模拟拓展{variant}）",
                options,
                answer,
                f"{explanation} 本题为同知识点的模考拓展题，重点仍是识别题干中的核心诊断或处理原则。",
                difficulty,
            )
        )
        index += 1
    return rows[:100]
